from copy import deepcopy
from pathlib import Path
from tempfile import NamedTemporaryFile
from ledger import Ledger

with NamedTemporaryFile(mode='w', prefix='.ledger-before-', suffix='.py', dir='.', delete=False) as backup:
    backup.write(Path('ledger.py').read_text())
    print('Saved original:', Path(backup.name).name)


def check(name, probe):
    try:
        probe()
    except Exception as error:
        print(f'REPRODUCED {name}: {type(error).__name__}: {error}')
    else:
        print(f'UNEXPECTED PASS {name}')


def input_alias():
    supplied = {'a': 100, 'b': 0}
    ledger = Ledger(supplied)
    supplied['a'] = 1
    assert ledger.balances['a'] == 100, 'caller input changes ledger balances'


def invalid_balance():
    try:
        Ledger({'a': True})
    except ValueError:
        return
    raise AssertionError('boolean balance accepted')


def invalid_transfer():
    ledger = Ledger({'a': 100, 'b': 0})
    try:
        ledger.transfer('a', 'b', -10, 'negative')
    except ValueError:
        return
    raise AssertionError(f'negative amount accepted: {ledger.balances}')


def insufficient_funds():
    ledger = Ledger({'a': 5, 'b': 0})
    before = deepcopy((ledger.balances, ledger.history))
    try:
        ledger.transfer('a', 'b', 6, 'overdraw')
    except ValueError:
        pass
    assert (ledger.balances, ledger.history) == before, f'failed transfer changed state: {ledger.balances}'


def unavailable_account():
    ledger = Ledger({'a': 5, 'b': 0})
    before = deepcopy((ledger.balances, ledger.history))
    try:
        ledger.transfer('a', 'missing', 2, 'missing')
    except Exception as error:
        assert isinstance(error, ValueError) and (ledger.balances, ledger.history) == before, f'{type(error).__name__}; balances now {ledger.balances}'
    else:
        raise AssertionError('missing account accepted')


def changed_replay():
    ledger = Ledger({'a': 100, 'b': 0})
    ledger.transfer('a', 'b', 20, 'one')
    try:
        ledger.transfer('a', 'b', 21, 'one')
    except ValueError:
        return
    raise AssertionError('changed replay payload accepted')


def receipt_alias():
    ledger = Ledger({'a': 100, 'b': 0})
    receipt = ledger.transfer('a', 'b', 20, 'one')
    receipt['amount'] = 999
    assert ledger.history['one']['amount'] == 20, 'returned receipt changes internal history'


def atomic_batch():
    ledger = Ledger({'a': 100, 'b': 0})
    before = deepcopy((ledger.balances, ledger.history))
    try:
        ledger.batch([
            dict(source='a', target='b', amount=20, key='one'),
            dict(source='a', target='b', amount=100, key='two'),
        ])
    except ValueError:
        pass
    assert (ledger.balances, ledger.history) == before, f'failed batch retained changes: {ledger.balances}, {ledger.history}'

for name, probe in [
    ('constructor input isolation', input_alias),
    ('constructor validation', invalid_balance),
    ('transfer validation', invalid_transfer),
    ('insufficient-funds rollback', insufficient_funds),
    ('unavailable-account rejection', unavailable_account),
    ('replay conflict', changed_replay),
    ('receipt isolation', receipt_alias),
    ('batch atomicity', atomic_batch),
]:
    check(name, probe)
